// Parse the AI response and validate data
try {
  const aiResponse = $input.first().json.message.content;
  const expense = JSON.parse(aiResponse);

  // Validate required fields
  if (typeof expense.amount !== 'number' || isNaN(expense.amount)) {
    throw new Error('Invalid amount');
  }

  // Set default values if missing
  expense.category = expense.category || 'Uncategorized';
  expense.merchant = expense.merchant || 'Unknown';
  expense.note = expense.note || $('Telegram Trigger').first().json.message.text;

  // Format for Google Sheets
  const now = new Date();
  return [{ json: {
    date: now.toISOString().split('T')[0],
    amount: expense.amount,
    category: expense.category,
    merchant: expense.merchant,
    note: expense.note,
    raw_message: $('Telegram Trigger').first().json.message.text
  } }];
} catch (error) {
  // If parsing fails, log the original message with error flag
  return [{ json: {
    date: new Date().toISOString().split('T')[0],
    amount: 0,
    category: 'ERROR',
    merchant: 'PARSE_FAILED',
    note: `Error: ${error.message}`,
    raw_message: $('Telegram Trigger').first().json.message.text
  } }];
}
